using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    public Error write_bitmap(Image bitmap,string destination)
    {
        string disk=destination.StartsWith("res://",StringComparison.Ordinal)||destination.StartsWith("user://",StringComparison.Ordinal)?ProjectSettings.GlobalizePath(destination):destination;return destination.GetExtension().ToLowerInvariant() switch{"png"=>bitmap.SavePng(disk),"jpg" or "jpeg"=>bitmap.SaveJpg(disk,.94f),"webp"=>bitmap.SaveWebp(disk,false,.9f),_=>Error.FileUnrecognized};
    }
    public string new_output_path(string nativePath){string basename=nativePath.GetBaseName();string output=basename+".png";int index=2;while(FileAccess.FileExists(output))output=basename+"-"+(index++)+".png";return output;}
    public void pack_project_textures(Resource snapshot)
    {
        _documents.pack_live_material_textures(snapshot);var packed=new Dictionary<ulong,PortableCompressedTexture2D>();if(snapshot.Get("pixel_selection").AsGodotObject() is ImageTexture selection){var compact=new PortableCompressedTexture2D{KeepCompressedBuffer=true};using var bitmap=selection.GetImage();compact.CreateFromImage(bitmap,PortableCompressedTexture2D.CompressionMode.Lossless);snapshot.Set("pixel_selection",compact);}foreach(var value in snapshot.Get("layers").AsGodotArray()){var layer=value.As<Resource>();foreach(string field in new[]{"texture","paint_base","mask"}){if(layer.Get(field).AsGodotObject() is not ImageTexture texture||texture.ResourcePath.Length>0)continue;ulong id=texture.GetInstanceId();if(!packed.TryGetValue(id,out var compact)){using var bitmap=texture.GetImage();if(bitmap==null)continue;compact=new PortableCompressedTexture2D{KeepCompressedBuffer=true};compact.CreateFromImage(bitmap,PortableCompressedTexture2D.CompressionMode.Lossless);packed[id]=compact;}layer.Set(field,compact);}}
    }
    public Settings prepare_save_targets(Control owner,bool writeImage,bool writeProject)
    {
        finish_pending(owner);var document=Document(owner);var source=owner.Get("source");if(document.Get("output_path").AsString().Length==0&&owner.Get("document_path").AsString().Length==0&&!(source.VariantType==Variant.Type.Object&&source.AsGodotObject() is ImageTexture))return new Settings{["choose_image"]=true};owner.Set("_busy",true);owner.Get("status").As<Label>().Text="Rendering and saving…";var snapshot=_documents.snapshot(document);snapshot.Set("workspace_state",ui_state(owner));var request=new Settings{["choose_image"]=false,["document"]=document,["version"]=owner.Get("_edit_version"),["snapshot"]=snapshot,["image_destination"]=writeImage?snapshot.Get("output_path"):Variant.From(""),["project_destination"]=writeProject?owner.Get("document_path"):Variant.From(""),["source"]=source,["flattened"]=owner.Get("_flatten_cache"),["write_image"]=writeImage,["write_project"]=writeProject};if(request["flattened"].AsGodotObject()==null)Renderer(owner).Set("document",snapshot);return request;
    }
    public void save_rendered(Control owner,Settings request,Image? flattened){request["flattened"]=flattened!=null?Variant.From(flattened):default;if(request["version"].AsInt64()==owner.Get("_edit_version").AsInt64())owner.Set("_flatten_cache",request["flattened"]);_renderer.sync(Renderer(owner),Document(owner));}
    public bool start_save_job(Control owner,Settings request)
    {
        var flattened=request["flattened"].As<Image>();if(flattened==null||flattened.IsEmpty()){owner.Get("status").As<Label>().Text="Could not render the image.";owner.Set("_busy",false);return false;}owner.Set("image",flattened);var snapshot=request["snapshot"].As<Resource>();using var thumb=(Image)flattened.Duplicate();thumb.Resize(192,Math.Max(1,Mathf.RoundToInt(192.0*flattened.GetHeight()/flattened.GetWidth())),Image.Interpolation.Bilinear);snapshot.Set("preview",ImageTexture.CreateFromImage(thumb));var document=Document(owner);if(request["document"].AsGodotObject()==document){document.Set("preview",snapshot.Get("preview"));document.Set("workspace_state",snapshot.Get("workspace_state"));}string imageDestination=request["image_destination"].AsString(),projectDestination=request["project_destination"].AsString();if(request["write_image"].AsBool()&&imageDestination.Length==0&&request["source"].VariantType==Variant.Type.Object&&request["source"].AsGodotObject() is ImageTexture embedded){embedded.SetImage(flattened);embedded.SetMeta("kiwi_image_document",snapshot);}request["error"]=(int)Error.Ok;var callback=Callable.From(()=>{Error error=Error.Ok;try{if(imageDestination.Length>0)error=write_bitmap(flattened,imageDestination);if(error==Error.Ok&&projectDestination.Length>0){pack_project_textures(snapshot);error=ResourceSaver.Save(snapshot,projectDestination);}}catch(Exception exception){GD.PushError("Image save failed: "+exception.Message);error=Error.Failed;}request["error"]=(int)error;});request["callback"]=callback;request["job"]=WorkerThreadPool.AddTask(callback,false,"Save Image Studio");return true;
    }
    public bool save_job_completed(Settings request)=>WorkerThreadPool.IsTaskCompleted(request["job"].AsInt64());
    public void complete_save_job(Control owner,Settings request)
    {
        WorkerThreadPool.WaitForTaskCompletion(request["job"].AsInt64());request.Remove("callback");if(request["document"].AsGodotObject()!=Document(owner)){owner.Set("_busy",false);return;}var status=owner.Get("status").As<Label>();int error=request["error"].AsInt32();if(error!=(int)Error.Ok){status.Text="Could not save the image document ("+error+").";owner.Set("_busy",false);return;}bool dirty=request["version"].AsInt64()!=owner.Get("_edit_version").AsInt64();owner.Set("_dirty",dirty);update_title(owner);bool writeProject=request["write_project"].AsBool(),writeImage=request["write_image"].AsBool();string project=owner.Get("document_path").AsString();if(writeProject&&project.Length>0){owner.Set("path",project);owner.Set("source",project);owner.EmitSignal("image_saved",project);}else if(writeImage){string output=Document(owner).Get("output_path").AsString();owner.EmitSignal("image_saved",output.Length==0?owner.Get("source"):Variant.From(output));}if(dirty)owner.EmitSignal("document_changed");status.Text="Saved · "+(writeImage?"image ":"")+(writeProject&&project.Length>0?"project":"");owner.Set("_busy",false);owner.Call("_refresh_project_files");
    }
    public void export_image(Control owner)
    {
        var dialog=new FileDialog{Access=FileDialog.AccessEnum.Filesystem,FileMode=FileDialog.FileModeEnum.SaveFile,UseNativeDialog=true,Title="Export image",Filters=new[]{"*.png ; PNG","*.jpg,*.jpeg ; JPEG","*.webp ; WebP"},CurrentFile="Image.png"};owner.AddChild(dialog);dialog.FileSelected+=destination=>{owner.Call("_export_to",destination);dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCenteredRatio(.75f);
    }
    public void complete_image_export(Control owner,string destination,Image? bitmap){if(bitmap==null||bitmap.IsEmpty()){owner.Get("status").As<Label>().Text="Could not render the image.";return;}var error=write_bitmap(bitmap,destination);owner.Get("status").As<Label>().Text=error==Error.Ok?"Exported "+destination.GetFile():"Export failed ("+(int)error+")";if(error==Error.Ok)owner.Call("_refresh_project_files");}
}
